/* Community Hub guides, researched and checked 24 Nov 2026 (official and sector sources). Built from the research files; videos left out until each one is checked. */
window.LCH_GUIDES={"careers":{"title":"Careers, apprenticeships and next steps (for young people and those who support them)","why":"Clear, honest information on options after school or college helps young people make choices that fit them, and helps parents and youth workers support them.","steps":["Explore options with the National Careers Service (free advice, skills assessment, course search).","Understand the routes: sixth form or college, T Levels, apprenticeships, university, traineeships/foundation routes, work and volunteering.","Apprenticeships: open to anyone 16+ not in full-time education; levels 2 to 7 across about 70 sectors; you earn a wage and pay no tuition fees. Foundation apprenticeships (level 2) are for 16–21s, and 22–24s with an EHCP, care leavers or prison leavers.","Search and apply through GOV.UK 'Find an apprenticeship'.","Get experience: volunteering, work experience, part-time work and clubs all count on applications.","Prepare: a short CV, a few practised interview answers, and a reference.","Check local colleges' entry requirements and open days (Luton: the hub's Built around your town pages)."],"tips":["Apply early: many apprenticeships close weeks before the start date.","Read the full job description and match your CV to it.","Ask a teacher, youth worker or employer for a reference in advance.","Use the free National Careers Service helpline or webchat.","Volunteering builds the skills employers ask for (teamwork, reliability).","Check pay: apprentices are entitled to at least the apprentice minimum wage (check the current rate on GOV.UK)."],"mistakes":["One generic CV for every application.","Missing closing dates.","Ignoring apprenticeships as a route to degrees (higher/degree apprenticeships exist)."],"legal":[{"item":"Apprentices must be paid at least the apprentice minimum wage","type":"legal requirement (rate not stated here; check GOV.UK)"}],"tools":[{"name":"National Careers Service: find a course / help with choices","url":"https://nationalcareers.service.gov.uk/find-a-course/help-with-choices"},{"name":"GOV.UK: Find an apprenticeship","url":"https://www.gov.uk/apply-apprenticeship"},{"name":"Skills for Careers: apprenticeships","url":"https://www.skillsforcareers.education.gov.uk/pages/training-choice/apprenticeships"}],"smr":["CV and portfolio design tips; for schools, a careers & pathways section built into your website (SMR Digital for schools)."],"elsewhere":["National Careers Service; school/college careers advisers; Luton Adult Learning; Jobcentre Plus youth hubs."],"sources":[{"url":"https://educationhub.blog.gov.uk/2026/02/national-apprenticeship-week-2026-how-apprenticeships-can-kick-start-your-career","checked":"24 Nov 2026"},{"url":"https://nationalcareers.service.gov.uk/find-a-course/help-with-choices","checked":"24 Nov 2026"},{"url":"https://www.skillsforcareers.education.gov.uk/pages/training-choice/apprenticeships","checked":"24 Nov 2026"}]},"free-kit-software":{"title":"Free kit and software","why":"Reuse networks and charity tech schemes can save hundreds or thousands of pounds.","steps":["Check your eligibility (registered charity, CIC, school, faith group, unregistered group).","For furniture and equipment, join a reuse network such as Warp It (free for schools, charities and community groups) or Globechain (free to join as a charity; you usually pay collection).","For software, register with Charity Digital Exchange (the UK TechSoup partner) to access discounted or donated products.","Apply to the big tech nonprofit programmes you need (Microsoft, Google, Canva and others).","Keep your charity details up to date; most schemes verify against official registers."],"tips":["Microsoft retired its free Microsoft 365 Business Premium and Office 365 E1 grants in 2025; most offers are now discounts.","Microsoft's nonprofit eligibility needs HMRC-recognised charity status, registration with the regulator and a non-discrimination policy.","Schools usually get education pricing rather than charity offers.","Canva offers a free nonprofit programme for eligible organisations.","Set alerts on reuse networks for items you need."],"mistakes":["Applying as an unregistered group to schemes that need charity registration.","Forgetting collection costs on 'free' items."],"legal":[],"tools":[{"name":"Warp It","url":"https://www.warp-it.co.uk/"},{"name":"Charity Digital Exchange","url":"https://charitydigital.org.uk/"},{"name":"Canva for Nonprofits","url":"https://www.canva.com/en_gb/help/canva-for-nonprofits/"}],"smr":["Setting up and branding your new tools (templates, email signatures, Canva brand kits)."],"elsewhere":["Charity Digital guides."],"sources":[{"url":"https://charitydigital.org.uk/landing-page/welcome-to-charity-digital-2","checked":"24 Nov 2026"},{"url":"https://www.civilsociety.co.uk/news/concerns-shared-as-microsoft-ends-free-software-offers-for-charities.html","checked":"24 Nov 2026"},{"url":"https://texaport.co.uk/blog/microsoft-nonprofit-guide","checked":"24 Nov 2026"}]},"funding-bid":{"title":"Write a funding bid","why":"Funders get far more applications than they can fund. Clear, specific, evidenced bids that match the funder's priorities stand out.","steps":["Shortlist funders whose priorities, area and size match your project; read their guidance fully.","Gather what you'll need: governing document, latest accounts, bank statement, trustee details, policies.","Write a 50–75 word summary of the project and adapt it for each funder.","Show the need with evidence: local statistics (see Luton in numbers), your own data, and quotes from the people you serve.","Explain what you'll do, how many people, how often, and what will change (outcomes).","Explain how you'll measure success.","Build the budget alongside the plan so the numbers match the activities.","Show community involvement: how people asked for this and helped shape it.","Get a 'critical friend' who knows the project to check it, especially the finances.","Submit early and note the decision timescale (some take months)."],"tips":["Tailor every bid; funders spot copy-and-paste.","Use their words: mirror their priorities and outcomes.","Give realistic numbers rather than leaving blanks or inflating them.","For a letter bid with no form, keep it to about two sides of A4.","Make sure organisation names and registration details exactly match official records.","For National Lottery Awards for All: two unrelated contacts with full details are needed, and the wrong bank statement is the most common error.","Don't start the project before you hear back.","Keep a library of reusable answers (organisation background, safeguarding, equality)."],"mistakes":["Not reading the guidance.","Unanswered questions or missing attachments.","Budget not matching the activities.","Wrong person signing.","Missing the deadline."],"legal":[{"item":"Use grants only for the agreed purpose and report as required","type":"legal/contractual requirement"},{"item":"Up-to-date Charity Commission / Companies House details","type":"required by many funders"}],"tools":[{"name":"NCVO: writing your application","url":"https://www.ncvo.org.uk/help-and-guidance/funding-income/all-about-grants/writing-your-application/"},{"name":"National Lottery: strengthening your Awards for All application","url":"https://www.tnlcommunityfund.org.uk/news/strengthening-your-awards-for-all-england-application-form"}],"smr":["Professional design for supporting documents (case for support, impact report, project one-pager).","The hub's Funding finder, bid checklist and Luton in numbers (free)."],"elsewhere":["Beds & Luton Community Foundation and funders' own pre-application calls.","Local CVS funding advice."],"sources":[{"url":"https://www.ncvo.org.uk/help-and-guidance/funding-income/all-about-grants/writing-your-application/","checked":"24 Nov 2026"},{"url":"https://www.tnlcommunityfund.org.uk/news/strengthening-your-awards-for-all-england-application-form","checked":"24 Nov 2026"}]},"fundraising-appeal":{"title":"Run a fundraising appeal","why":"A focused appeal with a clear target and regular updates raises far more than a general 'please donate'. Doing it properly also protects your reputation.","steps":["Decide the target and what it pays for in concrete units (e.g. 'a food parcel for a family for a week').","Write a short case for support: the need, what you'll do, the difference it makes, and why now.","Pick one donation page and one QR code and use them everywhere.","Plan the timeline: launch, weekly progress updates, a final push, and a thank-you.","Prepare content: a real story (with consent), photos, and progress graphics.","Ask partners, staff and volunteers to share on launch day.","Thank donors promptly, and publicly only with permission.","Close with the final total and what it achieved; keep donors updated afterwards."],"tips":["Say exactly how money will be used, and only promise what you'll actually spend it on.","If donations will go to general funds, say so; don't imply they're restricted.","Register with the Fundraising Regulator and show the badge where you fundraise.","Have a short complaints process and publish it.","Claim Gift Aid where eligible: it adds 25p per £1 from UK taxpayers.","For street collections in Luton, apply to the council at least a month ahead (no fee).","Check the Gambling Commission rules before any raffle or lottery.","Use progress bars and countdowns; momentum encourages giving."],"mistakes":["Vague asks with no target.","Saying funds go to a project when they go to general costs.","Running a raffle without checking the rules.","Forgetting to thank donors.","Collecting in the street without a permit."],"legal":[{"item":"Street collection permit (Luton: apply 1 month ahead, no fee, return form afterwards)","type":"legal requirement"},{"item":"House-to-house collection licence","type":"legal requirement"},{"item":"Lottery/raffle rules","type":"legal requirement"},{"item":"Commercial participator agreement and statement when a business promotes 'X% to charity'","type":"legal requirement"},{"item":"Fundraising Regulator registration","type":"good practice"}],"tools":[{"name":"Code of Fundraising Practice (from 1 Nov 2025)","url":"https://www.fundraisingregulator.org.uk/code"},{"name":"CIoF: legal and compliant fundraising for small charities","url":"https://ciof.org.uk/library/resources/legal-and-compliant-fundraising-a-guide-for-small-charities/"},{"name":"Luton street collection licence","url":"https://www.luton.gov.uk/business-licences-permits/licences-permits/business-licences/street-trading-street-collection"}],"smr":["Appeal campaign kit: posters, posts, progress graphics and thank-you posts (proof approval).","Donation page and QR codes (we link to your own platform; SMR never takes donations).","Impact report design for the end of the appeal."],"elsewhere":["Chartered Institute of Fundraising (free small charity membership).","Fundraising Regulator Code advice service."],"sources":[{"url":"https://www.fundraisingregulator.org.uk/code","checked":"24 Nov 2026"},{"url":"https://ciof.org.uk/library/resources/legal-and-compliant-fundraising-a-guide-for-small-charities/","checked":"24 Nov 2026"},{"url":"https://www.luton.gov.uk/business-licences-permits/licences-permits/business-licences/street-trading-street-collection","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/claim-gift-aid","checked":"24 Nov 2026"}]},"gdpr-data":{"title":"Data protection (GDPR) basics","why":"Every organisation that keeps people's details must look after them properly. Getting the basics right avoids complaints and builds trust.","steps":["List the personal data you hold, why, and where.","Pick a lawful basis for each use (often consent, contract or legitimate interests).","Write a short privacy notice and share it where you collect data.","Check whether you must pay the ICO data protection fee (use the ICO self-assessment; some organisations are exempt). Charities that aren't exempt pay the Tier 1 fee, £52 a year (£5 off by direct debit), whatever their size.","Keep data secure: strong passwords, 2-step login, locked files, limited access.","Only keep data as long as you need it.","Know what to do if data is lost (some breaches must be reported to the ICO within 72 hours).","Respond to requests for people's own data within one month."],"tips":["Use BCC or a mailing tool; never expose everyone's email addresses.","Only email people who agreed to hear from you; include an unsubscribe link.","Collect only what you need (often just name and email).","Get clear, written consent for photos of children.","Use the ICO's free self-assessment tools and small organisation advice."],"mistakes":["Group emails in CC.","Keeping old sign-up sheets for years.","No privacy notice."],"legal":[{"item":"UK GDPR principles, privacy notice, security, rights","type":"legal requirement"},{"item":"ICO fee unless exempt","type":"legal requirement"},{"item":"PECR rules for marketing emails/texts","type":"legal requirement"}],"tools":[{"name":"ICO: advice for small organisations","url":"https://ico.org.uk/for-organisations/advice-for-small-organisations/"}],"smr":["Privacy notices and consent forms laid out clearly (wording from ICO templates)."],"elsewhere":["ICO helpline and small business tools."],"sources":[{"url":"https://ico.org.uk/for-organisations/advice-for-small-organisations/","checked":"24 Nov 2026"},{"url":"https://ico.org.uk/for-organisations/data-protection-fee/","checked":"24 Nov 2026"},{"url":"https://ico.org.uk/fee-guide","checked":"24 Nov 2026"}]},"gift-aid":{"title":"Gift Aid basics","why":"Gift Aid adds 25p to every £1 donated by a UK taxpayer, often the easiest extra income a charity can get.","steps":["Check eligibility: your organisation must be recognised by HMRC as a charity or CASC for tax purposes.","Register with HMRC for charity tax purposes and get a charity reference.","Collect a Gift Aid declaration from each donor (paper, online or recorded verbally with a written record).","Keep records linking each donation to a declaration.","Claim online through HMRC Charities Online.","For small cash donations (£30 or less, e.g. bucket collections), check the Gift Aid Small Donations Scheme rules.","Reclaim regularly; payment usually arrives within about 5 weeks."],"tips":["Put the declaration on every donation form and donation page.","Donors must have paid enough UK tax to cover what you claim; say this clearly on the form.","Gift Aid can't usually be claimed where the donor gets a significant benefit (e.g. a ticket in return).","Use your donation platform's Gift Aid feature if it has one.","Keep declarations for HMRC audits.","Donor benefits must stay small: for gifts up to £100, benefits worth no more than 25% of the gift (larger gifts: 25% of the first £100 plus 5% of the rest, up to £2,500 a year per donor).","A valid declaration needs the donor's name and home address, your charity's name, which gifts it covers, and an explanation of the donor's tax responsibility; 'I am a UK taxpayer' alone isn't enough.","Sponsorship forms can double as Gift Aid declarations if the declaration is at the top of each sheet and each sponsor ticks for their own gift.","Keep declarations and records for 6 years after the accounting period (enduring declarations for as long as donations continue)."],"mistakes":["Claiming without a valid declaration.","Claiming on payments for goods, tickets or raffles.","Poor records.","Claiming Gift Aid on money a participant pays towards their own place in a challenge event."],"legal":[{"item":"Valid declarations and records","type":"legal requirement for claims"}],"tools":[{"name":"GOV.UK: claim Gift Aid","url":"https://www.gov.uk/claim-gift-aid"}],"smr":["Donation forms and posters with the Gift Aid declaration built in (wording from HMRC's model)."],"elsewhere":["HMRC Charities helpline.","Your accountant or independent examiner."],"sources":[{"url":"https://www.gov.uk/claim-gift-aid","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/government/publications/charities-detailed-guidance-notes/chapter-3-gift-aid","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/claiming-a-top-up-payment-on-small-charitable-donations","checked":"24 Nov 2026"},{"url":"https://www.ncvo.org.uk/help-and-guidance/running-a-charity/financial-management/tax-and-trading/gift-aid-and-gasds/gift-aid-small-donations-scheme-gasds","checked":"24 Nov 2026"}]},"impact-reporting":{"title":"Show your impact","why":"Funders, donors and your community want to see what difference you make. Simple, honest impact reporting wins repeat funding.","steps":["Write down the change you want to see (your outcomes), not just activities.","Map how your activities lead to those changes (a simple theory of change).","Choose 3–5 things to measure that you can realistically collect.","Collect a mix of numbers (people reached) and stories (quotes, case studies, with consent).","Review every few months and adjust what you do.","Share results in a short, visual report."],"tips":["Use free tools such as Inspiring Impact's self-assessment.","Collect feedback at the end of sessions with a 2-minute form.","Before/after questions show change better than satisfaction scores.","Pair every number with a human story.","Re-use the same report for funders, newsletters and your website."],"mistakes":["Counting only activities.","Collecting data you never use.","Using stories without consent."],"legal":[],"tools":[{"name":"Inspiring Impact (NPC) free tools","url":"https://www.thinknpc.org/publications/inspiring-impact-2/"}],"smr":["Professionally designed impact reports and infographics.","The hub's free impact report builder."],"elsewhere":["NPC / Inspiring Impact resources."],"sources":[{"url":"https://www.thinknpc.org/publications/inspiring-impact-2/","checked":"24 Nov 2026"}]},"legal-overview":{"title":"The legal basics at a glance","why":"Most community groups only need to get a handful of legal things right. This page gathers them in one place, with links to the full guides.","steps":["Know your structure: unincorporated group, charity (registered if income is £5,000+ a year, or any CIO) or CIC. This decides who is responsible and what you file each year.","Trustees: understand the six main duties in the Charity Commission's essential trustee guidance (CC3): carry out your purposes for public benefit, comply with your governing document and the law, act in the charity's best interests, manage resources responsibly, act with reasonable care and skill, and be accountable.","Safeguarding: named lead, policy, and the right DBS checks (rules changed 1 Sept 2026).","Data: lawful basis, privacy notice, security, and the ICO fee unless exempt (charities pay the Tier 1 fee of £52, or £47 by direct debit).","Fundraising: street collection permits, raffle/lottery rules, commercial participator agreements, and honesty about how money is used.","Events: Temporary Event Notice for alcohol or licensable activities (£21, under 500 people, at least 10 working days' notice), road closure permission, food hygiene.","Premises: fire risk assessment by the responsible person; health and safety risk assessment if you employ anyone.","Money: two signatories, proper records, annual accounts/returns, Gift Aid records kept for 6 years.","Employment: if you take on staff, contracts, right to work checks, payroll, pension auto-enrolment and employers' liability insurance."],"tips":["Put renewal dates (ICO fee, insurance, DBS rechecks, annual return) in one calendar.","Keep minutes of trustee decisions, especially risky ones.","Small charities can get free advice from local CVS bodies.","When in doubt about tax or VAT, ask HMRC's charities helpline or an accountant.","Review policies yearly; a short policy that's followed beats a long one that isn't."],"mistakes":["Assuming 'we're only volunteers' means no rules apply.","Missing the annual return deadline.","Not telling the regulator about a serious incident."],"legal":[{"item":"Everything in the steps above","type":"legal requirement where it applies"},{"item":"Policies (safeguarding, complaints, equality, data)","type":"expected by regulator and funders"}],"tools":[{"name":"Charity Commission: the essential trustee (CC3)","url":"https://www.gov.uk/government/publications/the-essential-trustee-what-you-need-to-know-cc3"},{"name":"GOV.UK: Temporary Event Notice","url":"https://www.gov.uk/temporary-events-notice"},{"name":"ICO fee guide","url":"https://ico.org.uk/fee-guide"}],"smr":["A clean, branded policy pack layout (your content, our design).","Signage for fire exits, safeguarding and privacy notices."],"elsewhere":["Charity Commission guidance; local CVS; HMRC charities helpline; a solicitor for anything contractual."],"sources":[{"url":"https://www.gov.uk/government/publications/the-essential-trustee-what-you-need-to-know-cc3","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/temporary-events-notice","checked":"24 Nov 2026"},{"url":"https://ico.org.uk/fee-guide","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/setting-up-charity","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/workplace-fire-safety-your-responsibilities","checked":"24 Nov 2026"}]},"local-press":{"title":"Get local press and media coverage","why":"A story in the local paper, radio or a news site reaches people your social media never will, and builds credibility with funders.","steps":["Find the story: something new, a local person, a number, a first, a milestone, or a link to something in the news. Ask 'why would a reader care?'.","Write a short press release: a clear headline, the key facts (who, what, when, where, why) in the first paragraph, a quote from a real person, then background and contact details.","Find the right journalist: someone who covers your topic or area at the outlet (local paper, BBC Three Counties Radio, Inspire FM, community news sites). Check their details are current.","Pitch by email: address them by name, say why it suits their section, paste the release into the email body (no attachments), add key dates, image links and interview availability. Keep the subject line short.","Send photos via a download link at high resolution (300 DPI for print), with credits and consent.","Follow up once politely after a reasonable wait, in the same email thread.","If they publish, thank them and share the coverage; if there's an error, tell them quickly and politely."],"tips":["Local media love local faces and real numbers.","Have a spokesperson ready to talk the same day.","Offer an exclusive to one outlet if the story is strong.","Keep a simple media list and note who covered you.","Use free templates (Media Trust press release template).","Tie stories to awareness days, Ramadan, Christmas or local events.","Make sure everyone in photos has consented.","Charities can apply to Media Trust's charity press programme with PA Media for wider distribution."],"mistakes":["Sending attachments only.","No clear story, just 'we exist'.","Mass emails to every journalist.","Chasing repeatedly."],"legal":[{"item":"Consent for photos and case studies","type":"legal/safeguarding"},{"item":"Copyright of photos (volunteer photographers own their photos unless signed over)","type":"legal"}],"tools":[{"name":"Media Trust: press releases, a charity's guide","url":"https://mediatrust.org/resource-hub/press-releases-a-charitys-guide/"},{"name":"Media Trust press release template (.docx)","url":"https://mediatrust.org/wp-content/uploads/2026/08/Press-release-template.docx"},{"name":"Media Trust charity press programme with PA Media","url":"https://mediatrust.org/press-release-support-for-charities/"}],"smr":["Press-ready photos and graphics, and a one-page media kit with your logo and facts.","Campaign visuals to go with the story."],"elsewhere":["Media Trust volunteering and resources; National Lottery grantees get the Media Trust toolkit."],"sources":[{"url":"https://mediatrust.org/resource-hub/press-releases-a-charitys-guide/","checked":"24 Nov 2026"},{"url":"https://mediatrust.org/resource-hub/writing-a-press-release-and-how-to-pitch-it/","checked":"24 Nov 2026"},{"url":"https://tnlcommunityfund.org.uk/funding/managing-your-grant/promoting-your-project/media-trust-toolkit","checked":"24 Nov 2026"},{"url":"https://www.bond.org.uk/news/2022/05/how-to-land-media-coverage-a-guide-for-small-ngos/","checked":"24 Nov 2026"}]},"partnerships":{"title":"Partnerships and joint bids","why":"Working together lets small groups bid for bigger funds, share costs and reach more people, but needs clear agreements.","steps":["Agree the shared goal and what each partner brings.","Choose a lead partner to hold the money and report.","Write a short partnership agreement: roles, money, data, reporting, what happens if someone leaves.","Build the bid together with one consistent voice.","Meet regularly and keep minutes.","Review and share credit fairly."],"tips":["Funders often like partnerships that avoid duplication.","Check partners' governance and safeguarding before you commit.","Agree how the money flows and when partners get paid.","Start with a small joint project to build trust."],"mistakes":["No written agreement.","Unclear lead partner.","One partner doing all the work."],"legal":[{"item":"Data sharing agreements when sharing personal data","type":"legal requirement"}],"tools":[{"name":"NCVO: about collaborative working","url":"https://www.ncvo.org.uk/help-and-guidance/running-a-charity/collaboration/about-collaborative-working/"}],"smr":["Joint campaign materials with both brands (proof approval)."],"elsewhere":["NCVO collaboration guidance; local CVS."],"sources":[{"url":"https://www.ncvo.org.uk/help-and-guidance/running-a-charity/collaboration/about-collaborative-working/","checked":"24 Nov 2026"}]},"photo-consent":{"title":"Photos, filming and consent","why":"Photos make your posts and reports come alive, but pictures of people (especially children) are personal data and a safeguarding matter. A simple policy and clear consent keep everyone safe.","steps":["Write a short photo and filming policy: why you take photos, where they're used, how long you keep them, and who to ask to remove one.","Choose a lawful basis for each use. Consent is common for publicity; schools may use public task or legitimate interests for some uses, but must offer a way to opt out.","Get consent in writing: say what the photo is for (website, social media, print), how long you'll keep it, and how to withdraw. For under-16s get a parent's consent and ask the child too; for 16–17s decide case by case.","Mark people who haven't consented (e.g. a coloured lanyard or sticker) so photographers can avoid them, without leaving them out of the activity.","Take photos on organisation devices, not personal phones, and store them securely with limited access.","Before posting, check: no names next to children's faces, no location tags, no uniform or badge that identifies a child's school, and remove image metadata.","Tell parents your filming rules before events, and ask them not to post other people's children publicly.","If someone withdraws consent, stop using the photo and delete it (items already printed can't be recalled, but don't reprint them)."],"tips":["Group, side-on or distant shots focused on the activity are safer than close-ups of one child.","Keep a simple consent log: who, when, what they agreed to.","Re-check consent each year for regular members.","Ask volunteer photographers to sign their copyright over to your organisation.","Use lower-resolution images online.","Treat AI risks seriously: posted images can be copied or altered.","Data protection usually doesn't stop parents taking photos of their own child for personal use; your policy can still set rules for your event.","From around 13, many children can understand how their image will be used, so ask them directly as well."],"mistakes":["Naming children in captions.","Posting group photos before checking for no-consent children.","Old consent forms reused for new purposes.","Photos left on volunteers' phones."],"legal":[{"item":"Lawful basis + transparency for using photos of identifiable people (UK GDPR)","type":"legal requirement"},{"item":"Stop using and delete when consent is withdrawn (if consent was your basis)","type":"legal requirement"},{"item":"Written photography policy","type":"safeguarding good practice (NSPCC)"},{"item":"Parental consent for under-16s","type":"good practice standard (NSPCC); schools follow DfE guidance"}],"tools":[{"name":"NSPCC Learning: photography and sharing images (includes an example policy)","url":"https://learning.nspcc.org.uk/safeguarding-child-protection/photography-and-sharing-images"},{"name":"DfE: taking and using photos and videos in schools","url":"https://www.gov.uk/guidance/data-protection-in-schools/taking-and-using-photos-and-videos-and-using-cctv-in-schools"},{"name":"ICO: photos at school (public advice)","url":"https://ico.org.uk/for-the-public/schools/photos/"}],"smr":["Consent forms and 'no photos please' lanyards/stickers designed and printed (proof approval).","Event photography briefings for your design team; we only use photos you've confirmed have consent."],"elsewhere":["NSPCC Learning helpline and templates.","ICO advice line for small organisations."],"sources":[{"url":"https://learning.nspcc.org.uk/safeguarding-child-protection/photography-and-sharing-images","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/guidance/data-protection-in-schools/taking-and-using-photos-and-videos-and-using-cctv-in-schools","checked":"24 Nov 2026"},{"url":"https://ico.org.uk/for-the-public/schools/photos/","checked":"24 Nov 2026"},{"url":"https://mediatrust.org/resource-hub/press-releases-a-charitys-guide/","checked":"24 Nov 2026"}]},"promote-event":{"title":"Promote your event","why":"Most events that struggle do so because people heard too late or only once. A simple countdown plan with one clear message and one booking link fills rooms.","steps":["Write one sentence: what, when, where, who it's for, and how to book.","Make one booking/RSVP link and a QR code, and use them on everything.","About 6 weeks out: save-the-date post and tell partners.","About 4 weeks out: poster and flyer up, Facebook event created, listed on the hub Events page.","About 2 weeks out: reminder posts with a new angle each time (speakers, food, activities, a volunteer's quote); send WhatsApp share text to partners.","1 week out: countdown story posts, a final call for volunteers.","Day before and on the day: practical info (parking, access, what to bring), then live stories.","Afterwards: thank-you post, photos (with consent), what was raised or achieved, and a save-the-date for next time."],"tips":["Repeat the same core message; many people only notice on the fifth or sixth time they see it.","Plan your big announcements in advance so each one leads to the next (a build-up, a peak on the day, then a gentle wind-down).","Keep a shared folder of logos, photos and short ready-made text so anyone can post.","Ask partners to post on the same day for a bigger lift.","Use the platform that suits each audience: Facebook for families and local groups, Instagram for visuals, TikTok for young people, WhatsApp for direct contact.","Put access information (step-free, parking, prayer room, halal food) in the post; it removes reasons not to come.","Pin the event post to the top of your profiles.","Collect RSVPs so you can send a reminder the day before."],"mistakes":["Announcing only a week before.","Different links in different places.","Posters with tiny dates or no 'how to book'.","Posting photos of children without consent."],"legal":[{"item":"Photo/film consent, especially for children","type":"legal (data protection) and safeguarding good practice"},{"item":"Only message people who agreed to hear from you","type":"legal requirement (PECR/GDPR)"}],"tools":[{"name":"Media Trust: charity social media on a limited timeframe","url":"https://mediatrust.org/resource-hub/charity-social-media-on-a-limited-timeframe/"},{"name":"Charity Digital: promoting a fundraising event on social media","url":"https://charitydigital.org.uk/topics/how-to-promote-your-fundraising-event-on-social-media-12134"}],"smr":["A full event campaign kit (poster, flyer, square and story posts, banner) in one look, at community rates, with proof approval.","Event countdown posts and a thank-you/impact post after the event.","QR codes and a booking page."],"elsewhere":["The hub Events page and Luton This Week.","Local radio (e.g. Inspire FM) and community Facebook groups."],"sources":[{"url":"https://charitydigital.org.uk/topics/how-to-promote-your-fundraising-event-on-social-media-12134","checked":"24 Nov 2026"},{"url":"https://mediatrust.org/resource-hub/charity-social-media-on-a-limited-timeframe/","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/government/publications/can-do-guide-for-organisers-of-voluntary-events/the-can-do-guide-to-organising-and-running-voluntary-and-community-events","checked":"24 Nov 2026"}]},"run-event":{"title":"Run a community event","why":"Events bring people together, raise money and build trust, but a little planning avoids the usual problems: no-shows, money muddles, safety gaps and licence surprises.","steps":["Set the purpose and a realistic size: who it is for, a minimum and maximum number, free or ticketed. Advance tickets or RSVPs help you judge demand.","Budget cautiously: assume income will be lower and costs higher than you hope, and keep a contingency even if you only aim to break even.","Book the venue and check what it already covers (insurance, alcohol licence, PRS/PPL music licences, fire procedures).","Check permissions early: road closures in Luton need at least 12 weeks' notice to the council Highways team; alcohol sales, paid entertainment or charging for entry may need a Temporary Event Notice (TEN); raffles and bingo have simple rules if kept small.","Do a risk assessment: walk the site, list what could seriously hurt someone, and decide how you will control it (trip hazards, crowding, food, weather, electrics, lost children).","Arrange insurance (public liability is strongly recommended, usually from £1m cover) and first aid.","If children or vulnerable adults attend, set out safeguarding: a named lead, checked helpers where required, photo consent, and a lost-child point.","Form small teams with one overall lead; brief everyone on the day plan and emergency procedure.","Promote it (see 'Promote your event').","Afterwards: count takings with two people present, bank promptly, thank volunteers and supporters, and note what to change next time."],"tips":["Put the date, time and place in the first line of every post and poster.","Ask the venue for its fire risk assessment and evacuation plan rather than writing your own from scratch.","Order change from your bank at least a week before.","Keep a 'day sheet' with key contacts, timings and who does what, printed and shared.","Use one booking or RSVP link everywhere so you can track numbers.","Plan for rain: cover, a second room, or a clear cancellation rule announced in advance.","Bouncy castles and rides should have current inspection certificates and be tethered.","Use an RCD trip device for any mains electrics outdoors.","Label food for common allergens even if not legally required, and have one person who knows the ingredients.","For a raffle at the event: keep it 'incidental' (prizes under the limit, expenses small, winners drawn at the event)."],"mistakes":["Applying for a road closure a few weeks before (Luton asks for 12 weeks).","No plan for cash handling.","Assuming the venue's insurance covers your activities.","Forgetting PRS/PPL if playing recorded music in a venue without a licence.","Not counting volunteers' DBS needs when children attend."],"legal":[{"item":"Temporary Event Notice for alcohol sales or other licensable activities: £21, fewer than 500 people at any time (including staff), up to 7 days, at least 10 clear working days' notice (late TENs 5–9 days, limited), up to 5 a year per person (50 with a personal licence) and 15 a year per premises","type":"legal requirement where applicable"},{"item":"Road closure permission from Luton Borough Council (apply 12+ weeks ahead)","type":"legal requirement if closing a road"},{"item":"Small-lottery/raffle rules (incidental lotteries: limited expenses and prize values, drawn at the event)","type":"legal requirement"},{"item":"Food hygiene and allergen information","type":"legal for registered food businesses; good practice for all"},{"item":"Public liability insurance","type":"strongly recommended (not legally required for most volunteer events)"},{"item":"Written risk assessment","type":"good practice; required in some circumstances (e.g. employers)"}],"tools":[{"name":"GOV.UK 'Can do' guide to organising voluntary and community events","url":"https://www.gov.uk/government/publications/can-do-guide-for-organisers-of-voluntary-events/the-can-do-guide-to-organising-and-running-voluntary-and-community-events"},{"name":"HSE event safety: getting started","url":"https://hse.gov.uk/Event-Safety/getting-started.htm"},{"name":"Luton Council: planning an event, road closures and highways","url":"https://www.luton.gov.uk/leisure-parks-culture/planning-organising-event/road-closures-highways"}],"smr":["Event poster, flyer, social posts and banners designed as one matching set (proof approval before anything is printed).","A booking/RSVP page or QR code for the event.","Printing and roller banners at community rates."],"elsewhere":["Luton Borough Council licensing and highways teams (road closures: 01582 510333).","Your venue's manager for licences and fire procedures.","Local CVS / voluntary sector support for insurance and volunteers."],"sources":[{"url":"https://www.gov.uk/government/publications/can-do-guide-for-organisers-of-voluntary-events/the-can-do-guide-to-organising-and-running-voluntary-and-community-events","checked":"24 Nov 2026"},{"url":"https://www.luton.gov.uk/leisure-parks-culture/planning-organising-event/road-closures-highways","checked":"24 Nov 2026"},{"url":"https://hse.gov.uk/Event-Safety/getting-started.htm","checked":"24 Nov 2026"},{"url":"https://www.ncvo.org.uk/help-and-guidance/safeguarding/certain-roles/fundraising-managers/types-associated-risks/events/","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/temporary-events-notice","checked":"24 Nov 2026"}]},"safeguarding-dbs":{"title":"Safeguarding and DBS checks","why":"Protecting children and adults at risk is a legal and moral duty. Since 1 September 2026, more volunteers need the higher level of DBS check.","steps":["Appoint a named safeguarding lead (and a deputy).","Write a safeguarding policy and procedures for reporting concerns; review yearly.","For each role, decide the right DBS check using the GOV.UK eligibility guidance.","Use safer recruitment: application, references, interview, checks before starting.","Train staff and volunteers at the right level and refresh regularly.","Set codes of conduct (e.g. no one-to-one in closed rooms, online contact rules).","Record concerns factually and report to the right agency (local children's/adult services, police in emergencies).","Encourage the free DBS Update Service so certificates can be re-checked."],"tips":["New from 1 Sept 2026: supervised volunteers who teach, train, care for or supervise children frequently (more than 3 days in 30, or overnight) are now in regulated activity and need an enhanced check with the children's barred list.","Volunteer DBS checks are free (you may still pay an umbrella body's admin fee).","In places of worship, roles like madrasa teaching or youth leadership follow the same thresholds; prayer-only faith leaders, caretakers and kitchen staff usually only need a basic check.","Days across different settings count together towards the 3-days-in-30 threshold.","Occasional helpers (e.g. a parent at a one-off event) are generally not affected.","Display who your safeguarding lead is.","Get consent before photographing children.","Keep records secure and confidential."],"mistakes":["Choosing the check level by job title rather than what the person actually does.","Letting someone start before checks are back.","No named lead.","Policy written but never trained."],"legal":[{"item":"Enhanced DBS with children's barred list for regulated activity","type":"legal requirement"},{"item":"Not allowing barred people into regulated activity","type":"legal requirement (offence)"},{"item":"Schools: Keeping Children Safe in Education","type":"statutory guidance"},{"item":"Safeguarding policy and named lead","type":"Charity Commission expectation for trustees; good practice for all"}],"tools":[{"name":"GOV.UK: regulated activity changes from 1 Sept 2026","url":"https://www.gov.uk/government/publications/working-or-volunteering-in-regulated-activity-with-children/regulated-activity-removal-of-the-supervision-exemption-comes-into-force-1-september-2026"},{"name":"GOV.UK: DBS checks in places of worship","url":"https://www.gov.uk/government/publications/dbs-checks-for-working-with-children-in-places-of-worship/dbs-checks-for-working-with-children-in-places-of-worship"},{"name":"NSPCC Learning: 8 steps to safeguarding","url":"https://learning.nspcc.org.uk/safeguarding-child-protection/8-steps-to-safeguarding-and-child-protection"},{"name":"NCVO: deciding which DBS checks","url":"https://www.ncvo.org.uk/help-and-guidance/safeguarding/dbs-checks/deciding-checks/"}],"smr":["Safeguarding posters (who is our lead, how to report) designed to your brand.","Policy documents laid out professionally (content must be your own/official templates)."],"elsewhere":["NSPCC Learning (training, standards).","DBS customer services 0300 020 0190.","Luton safeguarding partnership."],"sources":[{"url":"https://www.gov.uk/government/publications/working-or-volunteering-in-regulated-activity-with-children/regulated-activity-removal-of-the-supervision-exemption-comes-into-force-1-september-2026","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/government/publications/dbs-checks-for-working-with-children-in-places-of-worship/dbs-checks-for-working-with-children-in-places-of-worship","checked":"24 Nov 2026"},{"url":"https://learning.nspcc.org.uk/safeguarding-child-protection/8-steps-to-safeguarding-and-child-protection","checked":"24 Nov 2026"}]},"social-media":{"title":"Social media basics for small organisations","why":"Consistent, simple posting builds trust and brings in volunteers, donors and attendees. You don't need to be everywhere.","steps":["Trustees agree a short social media policy: who runs the accounts, who approves posts, how mistakes are handled, and guidelines for personal accounts (Charity Commission guidance).","Pick one or two platforms where your people already are (check where website visits and messages come from).","Choose a rhythm you can keep, e.g. once or twice a week, rather than bursts then silence.","Make a simple content calendar around your events, awareness days and the dates that matter to your community.","Each month, make one 'anchor' piece (a short video, story or photo set) and cut it into several posts.","Batch-create posts in one sitting and schedule them (Meta Business Suite is free for Facebook and Instagram).","Mix posts that inform, inspire, invite people to act, and thank people.","Reply to comments and messages within a day or two.","Check every few months what worked (clicks, shares, sign-ups) and do more of that."],"tips":["Share the load: trustees, volunteers and service users can film short clips.","Keep an 'evergreen' folder of impact numbers, quotes and good photos.","Turn one long piece into many: quotes become graphics, a talk becomes short clips.","Use consistent colours, fonts and logo placement so posts are recognisable.","Use stories for quick daily updates and posts for things people should find later.","Collaborate with partner accounts (Instagram collab posts) to reach both audiences.","Pin your three most important posts.","Add captions to videos: many people watch with the sound off.","Decide how you'll moderate comments (filters, limiting who can comment, hiding abuse) and look after whoever does it.","If something goes wrong, act fast: take it down if possible, decide whether to respond, keep a note of decisions and check whether the Charity Commission needs to be told.","Campaigning is allowed, but the rules on political activity still apply, especially near elections.","Staff and trustees can share personal views, but should make clear they're personal."],"mistakes":["Trying to run five platforms with one volunteer.","No call to action.","Posting identifiable photos of children without consent.","Letting messages go unanswered."],"legal":[{"item":"Consent for photos of identifiable people, especially children","type":"legal/safeguarding"},{"item":"Clear labelling of ads, sponsored posts or paid partnerships","type":"legal (ASA/CAP rules)"},{"item":"Charity political activity rules apply online","type":"legal requirement (charities)"}],"tools":[{"name":"Meta Business Suite (free scheduling for Facebook/Instagram)","url":"https://business.facebook.com/"},{"name":"Media Trust resource hub","url":"https://mediatrust.org/resource-hub/"}],"smr":["Branded post templates and a consistent look across platforms.","Monthly content packs or a managed social media plan.","A free social media audit and 5 posts for verified organisations (hub offer)."],"elsewhere":["Media Trust free resources and volunteering programme.","Charity Digital guides."],"sources":[{"url":"https://mediatrust.org/resource-hub/charity-social-media-on-a-limited-timeframe/","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/government/publications/charities-and-social-media/charities-and-social-media","checked":"24 Nov 2026"},{"url":"https://www.ncvo.org.uk/help-and-guidance/digital-technology/designing-services-products-and-activities/social-media-guidance-for-charities/","checked":"24 Nov 2026"},{"url":"https://charitydigital.org.uk/topics/how-to-promote-your-fundraising-event-on-social-media-12134","checked":"24 Nov 2026"}]},"sponsorship":{"title":"Business sponsorship","why":"Local businesses often want to support their community. Sponsorship gives them visibility and you funding, but it's a business deal, so it needs clear terms and the right tax treatment.","steps":["Decide what you can offer: logo on materials, naming an event, stalls at your event, website link, social posts, tickets.","Agree a short policy (trustees) on which businesses you'll partner with and what you won't promote.","Research the business: reputation, values, whether it fits your mission, any conflicts (e.g. a supplier, exclusivity demands, access to your supporters).","Make a simple one-page offer with packages and what each delivers.","Put it in writing: what they pay, what they get, logo use, how long, exclusivity, who approves publicity, how to end it.","Check VAT: if they get something in return (logo display, naming, promotion, tickets), it's usually a taxable supply, and sponsorship income can count towards the VAT registration threshold. A simple thank-you in a list of supporters is usually not.","Deliver what you promised and send them a short report with photos and numbers.","Ask early about renewing."],"tips":["Companies can usually deduct sponsorship from profits as a business expense, which is a selling point.","Separate a pure donation from sponsorship if they want both (the benefits mustn't depend on the donation).","Start with businesses your supporters already use.","Offer a 'community partner' tier for small local firms.","Keep proof of delivery (photos of banners, post screenshots).","Ask the business for staff volunteers too."],"mistakes":["No written agreement.","Promising exclusivity you can't keep.","Ignoring VAT.","Partners whose products clash with your values."],"legal":[{"item":"VAT on sponsorship where the sponsor gets benefits in return","type":"legal requirement (if VAT-registered or the income pushes you over the threshold)"},{"item":"Commercial participator rules if a business says 'X% of sales goes to charity'","type":"legal requirement"},{"item":"Written partnership agreement","type":"good practice (CIoF)"}],"tools":[{"name":"HMRC: sponsorship and VAT (Notice 701/41)","url":"https://www.gov.uk/guidance/sponsorship-and-vat-notice-70141"},{"name":"GOV.UK: companies sponsoring a charity","url":"https://www.gov.uk/tax-limited-company-gives-to-charity/sponsoring-a-charity"},{"name":"CIoF: a guide to corporate fundraising","url":"https://ciof.org.uk/library/types-of-fundraising/a-guide-to-corporate-fundraising/"}],"smr":["Sponsorship pack and package one-pager designed for you.","Sponsor banners, boards and co-branded posts (both logos approved through proofs)."],"elsewhere":["HMRC charities helpline; Chartered Institute of Fundraising; an accountant for VAT."],"sources":[{"url":"https://www.gov.uk/guidance/sponsorship-and-vat-notice-70141","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/tax-limited-company-gives-to-charity/sponsoring-a-charity","checked":"24 Nov 2026"},{"url":"https://ciof.org.uk/library/types-of-fundraising/a-guide-to-corporate-fundraising/","checked":"24 Nov 2026"},{"url":"https://www.fundraisingregulator.org.uk/code","checked":"24 Nov 2026"}]},"start-a-group":{"title":"Start a charity, CIC or community group","why":"The right structure affects what funding you can get, who carries liability, and how much paperwork you'll have.","steps":["Define your purpose and who benefits.","Choose a structure: unincorporated group/association (simplest), charity (CIO or charitable company), or CIC (a company for community benefit; can't be a charity).","Find at least three unrelated trustees/directors (most funders want this).","Write a governing document (constitution or articles); use a model from the regulator.","Open a bank account requiring two signatories.","Register: Charity Commission if a charity with income of £5,000+ a year or any CIO; Companies House + CIC Regulator for a CIC.","Register with HMRC if you'll claim Gift Aid.","Set up basic policies (safeguarding, equality, data protection, finance)."],"tips":["Most grant funders prefer charities or CICs limited by guarantee with 3+ unrelated directors.","A CIO gives limited liability without a separate company registration.","Unincorporated groups can start quickly and still get small grants.","Choose a name that isn't too similar to an existing charity.","Keep minutes of decisions from day one."],"mistakes":["Picking a CIC limited by shares and then finding many funders won't fund it.","Related trustees/directors.","No governing document."],"legal":[{"item":"Charity Commission registration (income £5,000+ or CIO)","type":"legal requirement"},{"item":"Annual returns/accounts","type":"legal requirement"}],"tools":[{"name":"GOV.UK: setting up a charity","url":"https://www.gov.uk/setting-up-charity"}],"smr":["Logo, brand kit and website for a new organisation, at community rates."],"elsewhere":["Charity Commission model governing documents.","Local CVS start-up support."],"sources":[{"url":"https://www.gov.uk/setting-up-charity","checked":"24 Nov 2026"}]},"training":{"title":"Free and low-cost training","why":"Trained trustees, staff and volunteers make better decisions, stay safe and win more funding. A lot of good training is free or cheap.","steps":["List the skills your team needs this year (safeguarding, first aid, trusteeship, food hygiene, fundraising, digital).","Start with free options: ICAEW's free trustee training modules, Charity Commission guidance, NSPCC Learning resources, and free webinars from sector bodies.","Join NCVO free if your income is under £30,000 a year; members get cheaper training (e.g. the trustee roles and duties eLearning, about half a day, £30 for small members).","Book role-specific training: safeguarding at the right level, first aid for event leads, food hygiene for kitchen volunteers.","Record who did what and when it expires.","Share learning: a 10-minute recap at team meetings."],"tips":["Ask your local CVS or council for subsidised courses.","Charity Digital and Media Trust run free digital and comms sessions.","Use Trustees' Week (November) for a governance refresher.","Funders often allow training costs in grant budgets.","Pair new trustees with an experienced one."],"mistakes":["Training once and never refreshing.","No record of certificates."],"legal":[{"item":"Food hygiene training appropriate to the role for food handlers","type":"legal requirement for food businesses"},{"item":"Safeguarding training","type":"expected good practice"}],"tools":[{"name":"ICAEW free trustee training modules","url":"https://www.icaew.com/technical/charity-community/trustee-training-modules"},{"name":"NCVO eLearning: roles and duties of trustees","url":"https://www.ncvo.org.uk/about-us/our-services/training/elearning-roles-duties-trustees"},{"name":"NSPCC Learning","url":"https://learning.nspcc.org.uk/"}],"smr":["Branded certificates for training you run (hub template service).","Workshop materials and slides designed for your sessions."],"elsewhere":["Local CVS training calendars; NCVO; ICAEW; NSPCC."],"sources":[{"url":"https://www.icaew.com/technical/charity-community/trustee-training-modules","checked":"24 Nov 2026"},{"url":"https://www.ncvo.org.uk/about-us/our-services/training/elearning-roles-duties-trustees","checked":"24 Nov 2026"},{"url":"https://learning.nspcc.org.uk/safeguarding-child-protection/8-steps-to-safeguarding-and-child-protection","checked":"24 Nov 2026"},{"url":"https://mediatrust.org/resource-hub/","checked":"24 Nov 2026"}]},"venue-risk":{"title":"Venue safety and risk assessment","why":"Anyone running activities in a building has duties to keep people safe; a short, real risk assessment is the simplest way to show you've thought it through.","steps":["Identify hazards: walk the space and list what could cause injury or illness.","Decide who might be harmed and how (children, older people, disabled visitors, volunteers).","Judge how likely and serious each risk is.","Remove the hazard or control it (barriers, signage, supervision, training).","Write it down and share it with your team.","Review it regularly and after any incident or change.","Fire: the responsible person must carry out and review a fire risk assessment and plan for emergencies."],"tips":["If you hire a hall, ask the owner for their fire risk assessment and evacuation plan.","Check exits are clear and fire alarms are tested.","Record accidents and near misses.","Keep first aid kits stocked and know who your first aider is.","Consider accessibility: step-free access, hearing loops, accessible toilets."],"mistakes":["Copying a template without walking the actual space.","Never reviewing it."],"legal":[{"item":"Risk assessment (employers must assess risks; written record expected in many cases)","type":"legal requirement for employers"},{"item":"Fire risk assessment by the responsible person for non-domestic premises","type":"legal requirement"}],"tools":[{"name":"HSE: managing risks and risk assessment","url":"https://www.hse.gov.uk/simple-health-safety/risk/index.htm"},{"name":"GOV.UK: workplace fire safety","url":"https://www.gov.uk/workplace-fire-safety-your-responsibilities"}],"smr":["Safety and exit signage, and printed procedures."],"elsewhere":["Bedfordshire Fire and Rescue Service business fire safety advice.","HSE templates."],"sources":[{"url":"https://www.hse.gov.uk/simple-health-safety/risk/index.htm","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/workplace-fire-safety-your-responsibilities","checked":"24 Nov 2026"}]},"volunteers":{"title":"Recruit and keep volunteers","why":"Good volunteer management means people stay, enjoy it and bring friends; poor management means constant re-recruiting.","steps":["Write a short role description for each role: tasks, time, skills, what they'll gain, who supports them.","Decide the checks needed for each role (see Safeguarding & DBS).","Advertise roles where your audience is, including the hub's Volunteering page.","Make signing up quick and reply within 48 hours.","Run an induction: welcome, tour, key policies, who to ask, emergency procedures.","Agree expenses up front and reimburse actual costs only.","Give ongoing support: regular check-ins and a named contact.","Thank and recognise volunteers often, and ask for feedback."],"tips":["Offer short, flexible and one-off roles; many people can't commit weekly.","Show a real volunteer's story (with consent).","Keep a simple volunteer agreement that describes expectations without creating a contract.","Only pay real out-of-pocket expenses; flat payments can create employment status.","Celebrate during Volunteers' Week each June.","Track hours and skills to show impact in funding bids.","Pair new volunteers with an experienced buddy.","Have a fair, clear process for problems.","Expenses: reimburse actual costs against receipts, set limits, pay within about a month, and use HMRC's mileage rate for drivers (check the current rate).","A role description must not read like a job contract or require set hours.","Check your insurance covers volunteers and any age limits; you may still want employers' liability cover even without staff.","Reassure volunteers on benefits: genuine expenses shouldn't affect them."],"mistakes":["No role description.","Slow replies to new applicants.","Paying flat 'expenses' that look like wages.","No induction or safeguarding briefing."],"legal":[{"item":"Right DBS checks for regulated activity (free for volunteers)","type":"legal requirement where applicable"},{"item":"Insurance covering volunteers","type":"strongly recommended"},{"item":"Avoid creating an employment relationship (rewards, obligations)","type":"legal risk"}],"tools":[{"name":"NCVO: involving volunteers","url":"https://www.ncvo.org.uk/help-and-guidance/involving-volunteers/"}],"smr":["Volunteer recruitment posters and posts.","Volunteer thank-you certificates via the hub's template service."],"elsewhere":["NCVO volunteering guidance.","Local volunteer centres and the hub Volunteering Opportunities page."],"sources":[{"url":"https://www.ncvo.org.uk/help-and-guidance/involving-volunteers/","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/guidance/how-to-manage-your-charitys-volunteers","checked":"24 Nov 2026"},{"url":"https://www.ncvo.org.uk/help-and-guidance/involving-volunteers/planning-for-volunteers/paying-volunteer-expenses","checked":"24 Nov 2026"},{"url":"https://www.gov.uk/volunteering/volunteers-rights","checked":"24 Nov 2026"}]},"winter-support":{"title":"Winter support and warm spaces","why":"Cold weather hits the people you support hardest. Knowing where to send people and how to run a warm space safely helps.","steps":["Keep an up-to-date list of local warm spaces, food support and cold-weather shelter (see Community Support Services).","If hosting a warm space, register or tell the council so people can find you.","Plan safeguarding, hot drinks/food hygiene and accessibility.","Share information in the languages your community uses.","Signpost to energy and money advice."],"tips":["Check the council's winter pages for current warm spaces.","Severe weather emergency shelter for rough sleepers is coordinated by councils; know how to refer.","Make your space welcoming: no questions asked, phone charging, Wi-Fi."],"mistakes":["Out-of-date opening times.","No plan for people who need urgent help."],"legal":[],"tools":[{"name":"Luton Council: Stay warm and well","url":"https://m.luton.gov.uk/Page/Show/news/Pages/Stay-Warm-and-Well-this-Winter.aspx"},{"name":"ELFT: Luton warm spaces","url":"https://www.elft.nhs.uk/service-users-and-carers/food-havens-warm-spaces-luton/luton-warm-spaces"},{"name":"Luton Council: Welcoming Spaces network (2025)","url":"https://www.luton.gov.uk/news/2025/new-welcoming-spaces-network-launched-strengthen-community-connections-across-luton"}],"smr":["Warm space posters and signage in multiple languages."],"elsewhere":["Luton Borough Council winter support.","Citizens Advice Luton."],"sources":[{"url":"https://m.luton.gov.uk/Page/Show/news/Pages/Stay-Warm-and-Well-this-Winter.aspx","checked":"24 Nov 2026"},{"url":"https://www.elft.nhs.uk/service-users-and-carers/food-havens-warm-spaces-luton/luton-warm-spaces","checked":"24 Nov 2026"},{"url":"https://www.luton.gov.uk/news/2025/new-welcoming-spaces-network-launched-strengthen-community-connections-across-luton","checked":"24 Nov 2026"}]}};
